class Solution {
  private int[][] table;
  private int[] log;

  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  private int range(int l, int r) {
    if (l > r) return 0;
    int k = log[r - l + 1];
    return gcd(table[k][l], table[k][r - (1 << k) + 1]);
  }

  public int maxValidSplits(int[] nums) {
    int n = nums.length;
    log = new int[n + 2];
    for (int i = 2; i <= n + 1; i++) log[i] = log[i / 2] + 1;
    table = new int[log[n] + 1][];
    table[0] = nums.clone();
    for (int k = 1; k < table.length; k++) {
      table[k] = new int[n];
      for (int i = 0; i + (1 << k) <= n; i++)
        table[k][i] = gcd(table[k - 1][i], table[k - 1][i + (1 << (k - 1))]);
    }
    int[] pre = new int[n], suf = new int[n];
    for (int i = 0; i < n; i++) pre[i] = gcd(i > 0 ? pre[i - 1] : 0, nums[i]);
    for (int i = n - 1; i >= 0; i--) suf[i] = gcd(i + 1 < n ? suf[i + 1] : 0, nums[i]);
    int best = 0;
    // no removal
    {
      int g = pre[n - 1], a = 0, b = n - 1;
      while (pre[a] != g) a++;
      while (suf[b] != g) b--;
      best = Math.max(best, b - a);
    }
    for (int r = 0; r < n; r++) {
      if (n - 1 < 2) break;
      int leftBase = r > 0 ? pre[r - 1] : 0, rightBase = r + 1 < n ? suf[r + 1] : 0;
      int g = gcd(leftBase, rightBase);
      // smallest kept index e with gcd of kept elements up to e equal to g
      int lo = 0, hi = n - 1;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        int pg = mid < r ? pre[mid] : gcd(leftBase, range(r + 1, mid));
        if (pg == g) hi = mid;
        else lo = mid + 1;
      }
      int e1 = lo;
      if (e1 == r) e1 = r + 1;
      // largest kept index e with gcd of kept elements from e equal to g
      lo = 0;
      hi = n - 1;
      while (lo < hi) {
        int mid = (lo + hi + 1) >>> 1;
        int sg = mid > r ? suf[mid] : gcd(range(mid, r - 1), rightBase);
        if (sg == g) lo = mid;
        else hi = mid - 1;
      }
      int e2 = lo;
      if (e2 == r) e2 = r - 1;
      if (e1 >= n || e2 < 0) continue;
      int a = e1 - (e1 > r ? 1 : 0), b = e2 - (e2 > r ? 1 : 0);
      best = Math.max(best, b - a);
    }
    return best;
  }
}
